<?php
$filter=in_array($_GET['request_status']??'', ['submitted','reviewing','approved','rejected','completed'],true)?$_GET['request_status']:'';
$where=$filter?' WHERE status=?':'';$q=$db->prepare('SELECT COUNT(*) FROM student_requests'.$where);$q->execute($filter?[$filter]:[]);$requestTotal=(int)$q->fetchColumn();$requestPage=page_number($requestTotal);$q=$db->prepare('SELECT * FROM student_requests'.$where.' ORDER BY id DESC LIMIT 20 OFFSET '.(($requestPage-1)*20));$q->execute($filter?[$filter]:[]);$requests=$q->fetchAll(PDO::FETCH_ASSOC);
?>
<article class="panel module-panel"><div class="panel-heading"><div><h2>Student request processing</h2><p>Review local portal requests. Approval records a decision; it does not update official school enrollment or graduation records.</p></div></div><form method="get" class="module-toolbar"><input type="hidden" name="page" value="source"><label>Status<select name="request_status"><option value="">All requests</option><?php foreach(['submitted','reviewing','approved','rejected','completed'] as $status):?><option <?=$filter===$status?'selected':''?>><?=$status?></option><?php endforeach;?></select></label><button class="button">Filter</button></form>
<?php foreach($requests as $request):?><details class="request-review"><summary>#<?=$request['id']?> / <?=h($request['kind'])?> / <?=h($request['student_number'])?> <span class="state-tag"><?=h($request['status'])?></span></summary><div class="investigation-body"><section><h3>Submitted details</h3><dl class="evidence"><?php foreach(json_decode($request['payload'],true)??[] as $key=>$value):?><dt><?=h(ucwords(str_replace('_',' ',$key)))?></dt><dd><?=h(is_array($value)?implode(', ',$value):$value)?></dd><?php endforeach;?></dl></section><form method="post" class="request-review-form"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><input type="hidden" name="request_id" value="<?=$request['id']?>"><label>Status<select name="request_status"><?php foreach(['reviewing','approved','rejected','completed'] as $status):?><option <?=$request['status']===$status?'selected':''?>><?=$status?></option><?php endforeach;?></select></label><label>Response to student<textarea name="response" rows="4" maxlength="2000" required><?=h($request['response']??'')?></textarea></label><button class="button primary">Save decision and response</button></form></div></details><?php endforeach;if(!$requests):?><p>No matching requests.</p><?php endif;pager($requestTotal,$requestPage,['page'=>'source','request_status'=>$filter]);?></article>
